def find_good_two_digit_numbers():
    good_numbers = []

    # Iterate through all 2-digit numbers m = 10*a + b where a != b and a, b are in {1..9}
    for a in range(1, 10):
        for b in range(1, 10):
            if a == b:
                continue

            m = 10 * a + b
            is_good = False

            # Case 1: Remove first digit (a). Resulting number is d = b.
            # d is always good (single digit). Check divisibility.
            # We check if m is divisible by b.
            if m % b == 0:
                # d=b, m%b == 0. This condition is equivalent to (10a+b)%b == 0, which means 10a % b == 0
                is_good = True

            # Case 2: Remove second digit (b). Resulting number is d = a.
            # d is always good (single digit). Check divisibility.
            # We check if m is divisible by a.
            if m % a == 0:
                # d=a, m%a == 0. This condition is equivalent to (10a+b)%a == 0, which means b % a == 0
                is_good = True

            if is_good:
                good_numbers.append(m)

    # Sort them for easier inspection
    good_numbers.sort()
    return good_numbers

