def is_valid_number(m):
    """Checks if m consists of distinct nonzero digits."""
    if m <= 0:
        return False
    s = str(m)
    digits = set()
    for char in s:
        digit = int(char)
        if digit == 0:
            return False
        if digit in digits:
            return False
        digits.add(digit)
    return True

def get_removals(m):
    """Generates all numbers formed by removing one digit of m."""
    s = str(m)
    removals = []
    for i in range(len(s)):
        new_s = s[:i] + s[i+1:]
        if new_s:
            removals.append(int(new_s))
    return removals

memo = {}

def is_good(m):
    """Determines if m is a 'good' number recursively."""
    if m in memo:
        return memo[m]

    if not is_valid_number(m):
        # Should not happen if called correctly, but handles constraint violation
        return False

    s_m = str(m)
    if len(s_m) == 1:
        # Base case: single-digit number is good (1-9)
        return True

    # Recursive step: Check removals
    removals = get_removals(m)

    for m_prime in removals:
        # Condition 1: m_prime is a divisor of m
        if m % m_prime == 0:
            # Condition 2: m_prime is a good number
            if is_good(m_prime):
                memo[m] = True
                return True

    memo[m] = False
    return False

